-- Archivo: sql/dml/003_carga_excel_equipos.sql
-- Autor: Carlos Geovanni Lopez Rodriguez
-- Descripcion: Carga instituciones, servicios solicitantes y equipos medicos
--   exportados de Libro1.xlsx (historial de reportes).
-- Dependencias: DDL actual o migraciones 001 y 003 (instituciones,
--   servicios_solicitantes y equipos_medicos).
-- Generado automaticamente; se puede ejecutar varias veces sin duplicar.
-- Un numero de bien identifica un solo equipo por institucion.

-- El archivo esta en UTF-8; evita que psql en Windows lo lea como WIN1252.
SET client_encoding = 'UTF8';

BEGIN;

INSERT INTO instituciones (nombre)
SELECT v.nombre
FROM (
    VALUES
        ('Hospital Departamental de Totonicapán'),
        ('Hospital Nacional de San Marcos "Dr. Moisés Villagrán Mazariegos"'),
        ('Hospital Regional de Occidente, Quetzaltenango'),
        ('Hospital de Especialidades Rodolfo Robles'),
        ('IGSS, Hospital General de Quetzaltenango'),
        ('Ortoimplantes')
) AS v(nombre)
WHERE NOT EXISTS (
    SELECT 1 FROM instituciones i WHERE LOWER(BTRIM(i.nombre)) = LOWER(BTRIM(v.nombre))
);

